-- =====================================================================
-- Migration: require a name on every short link
-- =====================================================================
-- Links made before this migration may have no name. Give each one its
-- destination as its name first, then require a name on every row.
--
-- Do not edit this file after it has run in a project. To change the database,
-- create a new migration with: supabase migration new <name>
-- =====================================================================

-- Fill in the name for any older link that has none, using its destination.
UPDATE public.urls SET name = original_url WHERE name IS NULL;

-- From now on, the database refuses a row without a name.
ALTER TABLE public.urls ALTER COLUMN name SET NOT NULL;
